import React, { Component } from "react";
import { Icon } from "@iconify/react";
import dotnetIcon from "@iconify/icons-logos/dotnet";
import csharpIcon from "@iconify/icons-logos/c-sharp";
import angularIcon from "@iconify/icons-logos/angular-icon";

class About extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isDownloading: false,
      downloadCount: 0
    };
  }

  handleDownload = () => {
    this.setState({ isDownloading: true });
    
    setTimeout(() => {
      const link = document.createElement('a');
      link.href = '/app.apk';
      link.download = 'mon-application.apk';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      this.setState(prevState => ({
        isDownloading: false,
        downloadCount: prevState.downloadCount + 1
      }));
      
      console.log('Téléchargement APK réussi');
    }, 1000);
  };

  render() {
    if (this.props.sharedBasicInfo) {
      var profilepic = "images/" + this.props.sharedBasicInfo.image;
    }
    if (this.props.resumeBasicInfo) {
      var sectionName = this.props.resumeBasicInfo.section_name.about;
      var hello = this.props.resumeBasicInfo.description_header;
      var about = this.props.resumeBasicInfo.description;
    }

    const { isDownloading, downloadCount } = this.state;

    return (
      <section id="about">
        <div className="col-md-12">
          <h1 style={{ color: "black" }}>
            <span>{sectionName}</span>
          </h1>
          <div className="row center mx-auto mb-5">
            <div className="col-md-4 mb-5 center">
              <div className="polaroid">
                <span style={{ cursor: "auto" }}>
                  <img
                    height="250px"
                    src={profilepic}
                    alt="Avatar placeholder"
                  />
                  {/* Icône .NET */}
                  <Icon
                    icon={dotnetIcon}
                    style={{ fontSize: "400%", margin: "9% 5% 0 5%" }}
                    title=".NET Framework"
                  />
                  
                  {/* Icône C# */}
                  <Icon
                    icon={csharpIcon}
                    style={{ fontSize: "400%", margin: "9% 5% 0 5%" }}
                    title="C# Programming Language"
                  />
                  
                  {/* Icône Angular */}
                  <Icon
                    icon={angularIcon}
                    style={{ fontSize: "400%", margin: "9% 5% 0 5%" }}
                    title="Angular Framework"
                  />
                </span>
              </div>
            </div>

            <div className="col-md-8 center">
              <div className="col-md-10">
                <div className="card">
                  <div className="card-header">
                    <span
                      className="iconify"
                      data-icon="emojione:red-circle"
                      data-inline="false"
                    ></span>{" "}
                    &nbsp;{" "}
                    <span
                      className="iconify"
                      data-icon="twemoji:yellow-circle"
                      data-inline="false"
                    ></span>{" "}
                    &nbsp;{" "}
                    <span
                      className="iconify"
                      data-icon="twemoji:green-circle"
                      data-inline="false"
                    ></span>
                  </div>
                  <div
                    className="card-body font-trebuchet text-justify ml-3 mr-3"
                    style={{
                      height: "auto",
                      fontSize: "132%",
                      lineHeight: "200%",
                    }}
                  >
                    <br />
                    <span className="wave">{hello} :) </span>
                    <br />
                    <br />
                    {about}
                    
                    {/* Section des compétences */}
                    <div className="mt-4">
                      <h5>Technologies maîtrisées :</h5>
                      <div className="d-flex justify-content-center mt-3">
                        <div className="text-center mx-3">
                          <Icon
                            icon={dotnetIcon}
                            style={{ fontSize: "300%" }}
                          />
                          <p>.NET</p>
                        </div>
                        <div className="text-center mx-3">
                          <Icon
                            icon={csharpIcon}
                            style={{ fontSize: "300%" }}
                          />
                          <p>C#</p>
                        </div>
                        <div className="text-center mx-3">
                          <Icon
                            icon={angularIcon}
                            style={{ fontSize: "300%" }}
                          />
                          <p>Angular</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Bouton de téléchargement APK */}
                <div className="text-center mt-4">
                  <button
                    onClick={this.handleDownload}
                    className="btn btn-success btn-lg"
                    disabled={isDownloading}
                  >
                    {isDownloading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2"></span>
                        Téléchargement en cours...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-download me-2"></i>
                        Télécharger l'APK
                      </>
                    )}
                  </button>
                  {downloadCount > 0 && (
                    <div className="mt-2 text-muted">
                      <small>Téléchargé {downloadCount} fois</small>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    );
  }
}

export default About;